head.script:
scwin.init = function() {
    //debugger;
    grd.setData(dataList1.getAllData());
    grd.setCellBackgroundColor(2, 2, 'yellow');
    grd.setCellBackgroundColor(8, 2, 'yellow');
    grd.setCellBackgroundColor(3, 2, 'yellow');
    grd.setCellInputType(2, 2, {
        inputType: "text",
        options: {
            allowChar: '0-5',
            displayFormat: '###,###,###,###'
        },
        value: '0123456789'
    });
    grd.setCellInputType(8, 2, {
        inputType: "text",
        options: {
            allowChar: '0-5'
        },
        value: '0123456789'
    });
    grd.setCellInputType(3, 2, {
        inputType: "secret",
        options: {
            maxlength: 5
        },
        value: '0123456789'
    });
}
scwin.trigger1_onclick = function(e) {
    grd.setCellAllowChar(2, 2, '0-3');
};
scwin.trigger3_onclick = function(e) {
    grd.setCellMaxLength(3, 2, 1);
};
scwin.trigger4_onclick = function(e) {
    grd.setCellDisplayFormat(2, 2, '##||##||##');
};
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.Dbclick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#trigger1', 'drag-n-drop', {
        dx: 100,
        dy: 100
    });
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일 실행 후 'setCellAllowChar' 버튼을 클릭한다.
    //1. After running the sample file, click the 'setCellAllowChar' button.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 0,123 값으로 보여진다.
    //1. It is shown as 0,123 value.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_cell_2_2').innerText == '0,123'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 'setCellMaxLength' 버튼을 클릭하고 값을 입력한다.
    //2. Click the 'setCellMaxLength' button and enter a value.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.Dbclick($p.id+'grd_cell_3_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_grd__dynamic_secret_3_2').setValue('1234')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 1자리수만 입력되어진다.
    //2. Only one digit is entered.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('G_grd__dynamic_secret_3_2').getValue().length == '1'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 'setCellDisplayFormat' 버튼을 클릭한다.
    //3. Click the 'setCellDisplayFormat' button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 01||23 값으로 보여진다.
    //3. It is shown as 01 || 23 value.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grd_cell_2_2').innerText == '01||23'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

scwin.onpageload = function() {
    scwin.init();
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 02-Mar-2018
    //End unitTest
}
